403:   class TiffImage {
404:   public:
405: 
406:     // Header class
407:     // ============
408:     // A TIFF file begins with an 8-byte image file header:
409:     // - Bytes 0-1: The byte order used within the file. Legal values are:
410:     //   - “II” (4949.H)
411:     //   - “MM” (4D4D.H)
412:     //   In the “II” format, byte order is always from the least significant
413:     //   byte to the most significant byte, for both 16-bit and 32-bit integers
414:     //   This is called little-endian byte order. In the “MM” format, byte order
415:     //   is always from most significant to least significant, for both 16-bit
416:     //   and 32-bit integers. This is called big-endian byte order.
417:     // - Bytes 2-3 An arbitrary but carefully chosen number (42) that further
418:     //   identifies the file as a TIFF file. The byte order depends on the value
419:     //   of Bytes 0-1.
420:     // - Bytes 4-7 The offset (in bytes) of the first IFD. The directory may be
421:     //   at any location in the file after the header but must begin on a word
422:     //   boundary.
423:     class Header {
424:       std::endian byteOrder_;
425:       uint32_t firstIFDOffset_;
426:     public:
427:       std::endian byteOrder() const { return byteOrder_; }
428: 
429:       bool equalsHostByteOrder() const {
430:         return std::endian::native == byteOrder_;
431:       }
432: 
433:       uint32_t firstIFDOffset() const { return firstIFDOffset_; }
434: 
435:       static Header read(std::istream& stream) {
436:         Header header;
437: 
438:         // Byte order
439:         uint16_t byteOrder = readValue<uint16_t>(stream); // 0x4949 for "II", 0x4D4D for "MM"
440:         if (byteOrder != 0x4949 && byteOrder != 0x4D4D) {
441:           throw std::runtime_error("Invalid byte order in TIFF header");
442:         }
443:         header.byteOrder_ =
444:           (byteOrder == 0x4949) ? std::endian::little : std::endian::big;
445: 
446:         // Swap byte order if necessary
447:         const bool mustSwap = !header.equalsHostByteOrder();
448: 
449:         // Magic number
450:         uint16_t magicNumber = readValue<uint16_t>(stream, mustSwap);
451:         if (magicNumber != 42) {
452:           throw std::runtime_error("Invalid magic number in TIFF header");
453:         }
454: 
455:         // First IFD offset
456:         uint32_t firstIFDOffset = readValue<uint32_t>(stream, mustSwap);
457:         if (firstIFDOffset < 8) { // Minimum size of TIFF header
458:           throw std::runtime_error("Invalid first IFD offset in TIFF header");
459:         }
460:         header.firstIFDOffset_ = firstIFDOffset;
461: 
462:         return header;
463:       }
464:     };
465: 
466:     // IFD class
467:     // =========
468:     // An Image File Directory (IFD) consists of a 2-byte count of the
469:     // number of directory entries (i.e., the number of fields), followed
470:     // by a sequence of 12-byte field entries, followed by a 4-byte offset
471:     // of the next IFD (or 0 if none).
472:     class IFD {
473:     public:
474: 
475:       // Entry class
476:       // ===========
477:       // Each IFD entry is a 12-byte structure that describes a field in the
478:       // image. The structure is as follows:
479:       // - Bytes 0-1: The Tag that identifies the field.
480:       // - Bytes 2-3: The field Type.
481:       // - Bytes 4-7: The number of values (Count) of the indicated Type.
482:       // - Bytes 8-11: The Value is expected to begin on a word boundary; the
483:       //   corresponding Value Offset will thus be an even number. This file
484:       //   offset may point anywhere in the file, even after the image data.
485:       //   The value of the field, or an offset to the value if it is too large
486:       //   to fit in 4 bytes.
487:       //
488:       // Sort Order
489:       // ----------
490:       // The entries in an IFD must be sorted in ascending order by Tag.
491:       // The Values to which directory entries point need not be in any
492:       // particular order in the file.
493:       //
494:       // Value/Offset
495:       // ------------
496:       // To save time and space the Value Offset contains the Value instead of
497:       // pointing to the Value if and only if the Value fits into 4 bytes. If
498:       // the Value is shorter than 4 bytes, it is left-justified within the
499:       // 4-byte Value Offset, i.e., stored in the lower-numbered bytes. Whether
500:       // the Value fits within 4 bytes is determined by the Type and Count of
501:       // the field.
502:       //
503:       // Count
504:       // -----
505:       // Count (called Length in previous versions of the specification) is the
506:       // number of values. Note that Count is not the total number of bytes.
507:       // For example, a single 16-bit word (SHORT) has a Count of 1; not 2.
508:       // The value of the Count part of an ASCII field entry includes the NUL.
509:       // If padding is necessary, the Count does not include the pad byte.
510:       //
511:       // Types
512:       // -----
513:       // The field types and their sizes are defined in the `Type` enum.
514:       class Entry {
515:       public:
516:         Tag tag() const { return tag_; }
517:         Type type() const { return type_; }
518:         uint32_t count() const { return count_; }
519:         const std::byte* values() const { return values_.data(); }
520: 
521:         template <typename T>
522:         std::span<const T> values() const {
523:           if (sizeof(T) != TiffCraft::typeBytes(type_)) {
524:             throw std::runtime_error("Invalid type size for values span");
525:           }
526:           return std::span<const T>(reinterpret_cast<const T*>(values_.data()), count());
527:         }
528: 
529:         uint32_t bytes() const { return count() * TiffCraft::typeBytes(type_); }
530: 
531:         static Entry read(std::istream& stream, bool mustSwap = false) {
532:           Entry entry;
533:           entry.tag_ = static_cast<Tag>(readValue<uint16_t>(stream, mustSwap));
534:           entry.type_ = static_cast<Type>(readValue<uint16_t>(stream, mustSwap));
535:           entry.count_ = readValue<uint32_t>(stream, mustSwap);
536: 
537:           // Read the value
538:           const uint32_t valueSize = entry.bytes();
539:           entry.values_.resize(valueSize);
540:           if (valueSize <= sizeof(uint32_t)) {
541:             // Value fits in 4 bytes, read directly
542:             const uint32_t value = readValue<uint32_t>(stream);
543:             std::memcpy(entry.values_.data(), &value, valueSize);
544:           }
545:           else {
546:             // Value is too large, read as an offset
547:             uint32_t valueOffset = readValue<uint32_t>(stream, mustSwap);
548:             if (valueOffset < 8 || valueOffset % 2 != 0) {
549:               throw std::runtime_error("Invalid value offset in TIFF entry");
550:             }
551:             readAt(stream, valueOffset, entry.values_.data(), valueSize);
552:           }
553: 
554:           // Swap values after reading them to treat them as an array, instead
555:           // of a single `uint32_t`. This is because the values may not be a
556:           // single `uint32_t` but rather a sequence of smaller types (e.g.,
557:           // uint16_t, uint8_t).
558:           // This is necessary to ensure that the values are correctly
559:           // interpreted according to their type.
560:           if (mustSwap) {
561:             swapArray(entry.values_.data(), entry.type_, entry.count_);
562:           }
563: 
