184:   // Define the expected structure of the TIFF header
185:   // It should be 8 bytes in total:
186:   struct HeaderBytes {
187:       uint16_t byteOrder;       // 0x4949 for "II", 0x4D4D for "MM"
188:       uint16_t magicNumber;     // 42
189:       uint32_t firstIFDOffset;  // Offset of the first IFD
190: 
191:       HeaderBytes(uint16_t bo = 0x4949, uint16_t mn = 42, uint32_t ifdOffset = 8)
192:           : byteOrder(bo), magicNumber(mn), firstIFDOffset(ifdOffset)
193:       {
194:         if (std::endian::native == std::endian::little && bo == 0x4D4D // "MM" big-endian
195:             || std::endian::native == std::endian::big && bo == 0x4949) { // "II" little-endian
196:           magicNumber = std::byteswap(magicNumber);
197:           firstIFDOffset = std::byteswap(firstIFDOffset);
198:         }
199:       }
200: 
201:       std::ostream& write(std::ostream& os) const {
202:         auto startPos = os.tellp();
203:         os.write(reinterpret_cast<const char*>(&byteOrder), sizeof(byteOrder));
204:         os.write(reinterpret_cast<const char*>(&magicNumber), sizeof(magicNumber));
205:         os.write(reinterpret_cast<const char*>(&firstIFDOffset), sizeof(firstIFDOffset));
206:         auto endPos = os.tellp();
207:         if (endPos - startPos != sizeof(HeaderBytes)) {
208:           throw std::runtime_error("HeaderBytes size mismatch");
209:         }
210:         return os;
211:       }
212:   };
